-- One-time guarded private research intake: 2004 DR-Z400SM, 2005 GSX-R1000 K5, 1999 YZF-R6.
-- Never generalise a year-specific specification to another model or production year.
DO $$
DECLARE matched integer; inserted integer; pub_before integer; pub_after integer;
BEGIN
 SELECT count(*) INTO pub_before FROM public.motorcycle_universal_published_sections_v1;
 WITH expected(id,make,model) AS (VALUES (952,'Suzuki','DR-Z400SM'),
(968,'Suzuki','GSX-R1000 K5'),
(722,'Yamaha','YZF-R6'))
 SELECT count(*) INTO matched FROM expected e
 JOIN public.motorcycle_catalog_models m ON m.id=e.id AND m.manufacturer=e.make AND m.model=e.model
 WHERE NOT EXISTS(SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s WHERE s.entity_type='model' AND s.model_id=e.id)
 AND NOT EXISTS(SELECT 1 FROM public.motorcycle_catalog_model_aliases a WHERE a.alias_model_id=e.id AND a.review_status<>'approved');
 IF matched<>3 THEN RAISE EXCEPTION 'Model identity/alias/staging changed; abort (% models)',matched; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.slot,v.title,v.content,'draft','factory_exact_year_source:'||v.source_url,NULL
 FROM (VALUES (952,1,'Model introduction','{"summary":"Suzuki developed the DR-Z400SM as a road-focused supermoto derivative of its DR-Z400S dual-purpose motorcycle.","source_name":"Suzuki original factory archive","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_111.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Historical source capture only. Retain exact variant/year scope. No rights or publication granted."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_111.php'),
(952,7,'Documented model history','{"summary":"Suzuki''s factory digital archive identifies the DR-Z400SM as a 2004 variant, distinct from the DR-Z400S launched in 2000.","source_name":"Suzuki original factory archive","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_111.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Historical source capture only. Retain exact variant/year scope. No rights or publication granted."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_111.php'),
(952,12,'Original-year engineering','{"summary":"The 2004 DR-Z400SM combines a liquid-cooled single-cylinder four-stroke with inverted front forks and 17-inch road wheels; later equipment needs its own checks.","source_name":"Suzuki original factory archive","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_111.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Historical source capture only. Retain exact variant/year scope. No rights or publication granted."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/dual_111.php'),
(968,1,'Model introduction','{"summary":"The 2005 K5 revision of the Suzuki GSX-R1000 pursued a more compact chassis and stronger performance than its predecessor.","source_name":"Suzuki original factory archive","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Historical source capture only. Retain exact variant/year scope. No rights or publication granted."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php'),
(968,7,'Documented model history','{"summary":"Suzuki''s archive records the 2005 GSX-R1000 as a substantial model revision, with changes to engine, cooling, ergonomics and handling.","source_name":"Suzuki original factory archive","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Historical source capture only. Retain exact variant/year scope. No rights or publication granted."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php'),
(968,12,'Specific 2005 engineering','{"summary":"The archive specifies a 999 cc liquid-cooled inline-four and back-torque-limiting clutch for the 2005 GSX-R1000; these details apply to K5, not all GSX-R1000 years.","source_name":"Suzuki original factory archive","source_url":"https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Historical source capture only. Retain exact variant/year scope. No rights or publication granted."}'::jsonb,'https://www.globalsuzuki.com/motorcycle/smgs/digital-archive/2_bike/sports_080.php'),
(722,1,'Model introduction','{"summary":"The Yamaha YZF-R6 established a highly focused 600-class sportbike combining agile chassis geometry with a high-revving four-cylinder engine.","source_name":"Yamaha original factory archive","source_url":"https://global.yamaha-motor.com/showroom/cp/collection/yzf-r6/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Historical source capture only. Retain exact variant/year scope. No rights or publication granted."}'::jsonb,'https://global.yamaha-motor.com/showroom/cp/collection/yzf-r6/'),
(722,7,'Documented model history','{"summary":"Yamaha''s Communication Plaza dates its original production YZF-R6 exhibit to 1999 and records the model''s initial design focus on lightweight, responsive handling.","source_name":"Yamaha original factory archive","source_url":"https://global.yamaha-motor.com/showroom/cp/collection/yzf-r6/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Historical source capture only. Retain exact variant/year scope. No rights or publication granted."}'::jsonb,'https://global.yamaha-motor.com/showroom/cp/collection/yzf-r6/'),
(722,12,'Original-generation engineering','{"summary":"Yamaha''s 1999 YZF-R6 used a liquid-cooled 599 cc DOHC inline-four, Deltabox II frame and ram-air intake; specification changes by year are not included.","source_name":"Yamaha original factory archive","source_url":"https://global.yamaha-motor.com/showroom/cp/collection/yzf-r6/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Historical source capture only. Retain exact variant/year scope. No rights or publication granted."}'::jsonb,'https://global.yamaha-motor.com/showroom/cp/collection/yzf-r6/')) v(model_id,slot,title,content,source_url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>9 THEN RAISE EXCEPTION 'Expected nine draft sections, inserted %',inserted; END IF;
 SELECT count(*) INTO pub_after FROM public.motorcycle_universal_published_sections_v1;
 IF pub_before<>pub_after THEN RAISE EXCEPTION 'Public projection changed unexpectedly'; END IF;
END $$;